  'chat.designToolbox.action.visual-polish.badge': 'Pulido',
  'chat.designToolbox.action.visual-polish.description': 'Audita la jerarquía visual, la tipografía, el espaciado, el comportamiento adaptable, la accesibilidad y la calidad de entrega.',
  'chat.designToolbox.action.image-gen.title': 'Generar imágenes / referencias visuales',
  'chat.designToolbox.action.image-gen.badge': 'Imagen',
  'chat.designToolbox.action.image-gen.description': 'Genera referencias de sección, recursos, iconos, imágenes sociales o un moodboard para la página actual.',
  'chat.designToolbox.action.chart-gen.title': 'Generar gráficos / diagramas',
  'chat.designToolbox.action.chart-gen.badge': 'Gráficos',
  'chat.designToolbox.action.chart-gen.description': 'Genera ECharts, React Flow, diagramas, paneles, mapas de relaciones o recursos de visualización de datos.',
  'chat.designToolbox.action.logo-gen.title': 'Generar logo / identidad',
  'chat.designToolbox.action.logo-gen.badge': 'Logo',
  'chat.designToolbox.action.logo-gen.description': 'Crea líneas de logo, wordmarks, lockups, marcas y prompts de sistema de identidad para la marca actual.',
  'chat.designToolbox.action.plan-outline.title': 'Generar esquema de PPT a partir de una idea',
  'chat.designToolbox.action.plan-outline.badge': "Plan",
  'chat.designToolbox.action.plan-outline.description': 'Convierte una idea en bruto en un esquema de presentación editable en Markdown antes de crear las diapositivas.',
