  'chat.designToolbox.prompt.processRule': 'Regla de flujo de trabajo: define primero el objetivo estético y las restricciones, luego busca y empareja recursos; cuando haga falta que el usuario elija, genera un question-form estructurado con respuestas personalizadas editables y continúa tras la confirmación.',
