  'designFiles.documentTemplate.titleFallback': 'Documento',
  'designFiles.documentTemplate.goalHeading': 'Objetivo',
  'designFiles.documentTemplate.goalBody': 'Describe qué debe generar, editar o decidir OpenDesign a partir de este documento.',
  'designFiles.documentTemplate.capabilitiesHeading': 'Cómo usar este documento',
  'designFiles.documentTemplate.capabilityMarkdown': 'Usa cualquier formato Markdown: encabezados, tablas, listas de tareas, enlaces, citas, bloques de código e imágenes.',
  'designFiles.documentTemplate.capabilityAgent': 'El agente de OpenDesign puede leer y editar este archivo, y usarlo como contexto del proyecto.',
  'designFiles.documentTemplate.capabilityImages': 'Pega imágenes o arrastra archivos de imagen al editor; las imágenes subidas se insertan en el cursor.',
  'designFiles.documentTemplate.scenarioHeading': 'Guía por escenario',
  'designFiles.documentTemplate.scenario.prototype': 'Para prototipos, resume el objetivo del producto, los usuarios, los flujos, las pantallas, los módulos, los estados de interacción, los puntos de ruptura responsive y los tokens de diseño como color, tipografía, espaciado, radio y movimiento.',
  'designFiles.documentTemplate.scenario.wireframe': 'Para wireframes, describe el flujo de usuario, la lista de pantallas, la jerarquía del diseño, los bloques de contenido, las restricciones de baja fidelidad y las preguntas que debe responder la estructura antes del diseño visual.',
  'designFiles.documentTemplate.scenario.mobile': 'Para apps móviles, enumera las plataformas de destino, las pantallas, el modelo de navegación, los gestos, los patrones nativos, los tamaños de dispositivo, los estados y los tokens de diseño móviles.',
  'designFiles.documentTemplate.scenario.slideDeck': 'Para diapositivas, escribe un esquema de PPT paginado: una sección por diapositiva con título, propósito, mensaje clave, evidencias, dirección visual, notas del orador y necesidades de exportación.',
  'designFiles.documentTemplate.scenario.document': 'Para documentos, define la audiencia, el tono, la estructura de secciones, el material de origen, las citas o datos, las expectativas de maquetación y los requisitos de PDF/exportación.',
  'designFiles.documentTemplate.scenario.image': 'Para imágenes, especifica el sujeto, la relación de aspecto, la composición, el estilo visual, los tokens de marca, los archivos de referencia y las restricciones negativas.',
  'designFiles.documentTemplate.scenario.video': 'Para vídeo, redacta un storyboard con escenas, tiempos, subtítulos, movimiento, recursos, notas de audio y formato de salida.',
  'designFiles.documentTemplate.scenario.hyperframes': 'Para HyperFrames, describe la pieza de movimiento HTML: escenas, línea de tiempo, subtítulos, momentos reactivos al audio, transiciones y requisitos de captura/exportación.',
  'designFiles.documentTemplate.scenario.audio': 'Para audio, define la dirección de voz o música, la duración, el ambiente, el guion o texto, el ritmo, las notas de pronunciación y el uso final.',
  'designFiles.documentTemplate.scenario.liveArtifact': 'Para artefactos en vivo, describe las fuentes de datos, la frecuencia de actualización, los widgets, los filtros, las interacciones, los estados vacío/cargando/error y las alertas o automatizaciones.',
  'designFiles.documentTemplate.scenario.designSystem': 'Para sistemas de diseño, enumera los objetivos de marca, los tokens, la tipografía, el color, el espaciado, los componentes, los recursos, las referencias y las reglas que seguir o evitar.',
  'designFiles.documentTemplate.scenario.default': 'Describe la audiencia, el entregable, el contenido necesario, las referencias, las restricciones y el aspecto que debe tener el resultado terminado.',
  'designFiles.documentTemplate.nextHeading': 'Siguiente paso',
  'designFiles.documentTemplate.nextBody': 'Revisa y edita este documento y luego pide a OpenDesign que genere, revise u opere a partir de él.',

