  'nextStep.createDesignSystemTitle': 'Crear sistema de diseño',
  'nextStep.createDesignSystemBody': 'Duplica este proyecto en un espacio de trabajo de sistema de diseño e inicia una pasada del agente con todos los archivos y referencias actuales.',
  'nextStep.createDesignSystemBusy': 'Creando sistema de diseño...',
  'nextStep.contribute': 'Contribuir',
  'nextStep.planGenerateTitle': "Generate from document",
  'nextStep.planGenerateBody': 'Usa el plan Markdown aprobado como fuente de verdad para la siguiente ejecución de diseño.',
  'nextStep.planImproveTitle': 'Mejorar documento',
  'nextStep.planImproveBody': 'Afina el documento del plan actual antes de generar el artefacto final.',
  'nextStep.planGeneratePrompt': 'Usa `{file}` como fuente de verdad. Lee primero el documento, conserva sus decisiones y genera después el artefacto de diseño final que coincida con él. Si es un esquema de diapositivas, genera la presentación; si es un PRD o plan de prototipo, genera el prototipo o los wireframes; si es un storyboard o brief creativo, genera el artefacto visual o multimedia correspondiente. Antes de generar, señala cualquier TODO bloqueante o contradicción que no puedas resolver.',
  'nextStep.planImprovePrompt': 'Lee `{file}` y mejóralo en el propio archivo como documento de plan editable. Afina el alcance, completa las secciones débiles, añade las comprobaciones de aceptación que falten y conserva los TODO y preguntas abiertas donde aún haga falta información del usuario. No generes todavía el artefacto de diseño final.',
  'nextStep.planImproveArtifactTitle': 'Mejorar artefacto',
  'nextStep.planImproveArtifactBody': 'Sigue iterando el artefacto generado en lugar de volver a la planificación.',
  'nextStep.planImproveArtifactPrompt': 'Mejora `{artifact}` en el propio archivo. Conserva el artefacto actual que funciona y aplica las mejoras de producto, visuales, de interacción y de contenido con mayor impacto. Conserva el comportamiento que ya funciona y resume después los archivos modificados y los riesgos pendientes.',
  'nextStep.planMergeTitle': 'Alinear documento y artefacto',
  'nextStep.planMergeBody': 'Concilia el plan y el artefacto generado para que avancen juntos.',
  'nextStep.planMergePrompt': 'Lee `{document}` y `{artifact}` juntos. Trata el documento como la intención y el artefacto como la implementación actual. Concílialos: actualiza el artefacto para que coincida con las decisiones confirmadas, actualiza el documento solo donde esté obsoleto y conserva TODO y preguntas abiertas explícitos para lo que siga sin resolverse. Conserva el comportamiento actual que funciona y resume qué cambió en ambos archivos.',

  'nextStep.projectContinueTitle': 'Seguir trabajando',
